def calculate_resource_ceiling_priority_single_processor(resource_j, tasks_using_resource_j, task_priorities):
    max_priority = -1 # Assuming priorities are non-negative integers, higher value means higher priority
    for task in tasks_using_resource_j:
        if task_priorities[task] > max_priority:
            max_priority = task_priorities[task]
    return max_priority

def calculate_task_wcet_single_processor(task_i, wcet_i_base, resources_used_by_task_i, resource_access_counts, resource_critical_section_times):
    total_resource_time = 0
    for resource_j in resources_used_by_task_i:
        total_resource_time += resource_access_counts[task_i][resource_j] * resource_critical_section_times[resource_j]
    C_i = wcet_i_base + total_resource_time
    return C_i

def calculate_blocking_term_single_processor(task_i, c_hat_value, b_value):
    B_i = max(c_hat_value, b_value)
    return B_i

import math

def calculate_response_time_single_processor(task_i, C_i, B_i, hp_tasks, task_periods, task_wcets, deadline_i):
    R_i_current = C_i + B_i
    while True:
        interference = 0
        for task_j in hp_tasks:
            interference += math.ceil(R_i_current / task_periods[task_j]) * task_wcets[task_j]

        R_i_next = C_i + B_i + interference

        if R_i_next == R_i_current:
            return R_i_next
        elif R_i_next > deadline_i: # Optimization: if it exceeds deadline, it's unschedulable
            return R_i_next
        else:
            R_i_current = R_i_next

def calculate_local_resource_ceiling_priority(resource_j, processor_k, tasks_using_resource_j, task_to_processor_map, task_priorities):
    max_local_priority = -1
    for task in tasks_using_resource_j:
        # Check if the task is allocated to processor_k
        if task_to_processor_map[task] == processor_k:
            if task_priorities[task] > max_local_priority:
                max_local_priority = task_priorities[task]
    return max_local_priority

def calculate_task_wcet_mrsp(task_i, wcet_i_base, resources_used_by_task_i, resource_access_counts, resource_execution_costs_ej):
